CREATE OR REPLACE FUNCTION public.validate_driver_assignment() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.route_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.routes r WHERE r.id=NEW.route_id AND r.company_id=NEW.company_id AND r.user_id=NEW.user_id) THEN RAISE EXCEPTION 'Assign a route belonging to this company'; END IF; IF NEW.route_id IS NOT NULL AND NEW.role NOT IN ('Driver','Senior Driver','Ticket Inspector') THEN RAISE EXCEPTION 'Only drivers, senior drivers and ticket inspectors can be assigned to bus routes'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.check_operating_fleet_frequency() RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public' AS $function$ DECLARE r record; needed integer; crew integer; BEGIN
FOR r IN SELECT rt.*, (SELECT count(*) FROM public.buses b WHERE b.route_id=rt.id AND b.company_id=rt.company_id AND b.status='In service') AS allocated, (SELECT count(*) FROM public.buses b WHERE b.route_id=rt.id AND b.company_id=rt.company_id AND b.status='Broken down') AS broken FROM public.routes rt WHERE rt.company_id=NEW.company_id AND (rt.contract_end_day IS NULL OR rt.contract_end_day>=NEW.day) LOOP
needed=ceil((2*r.journey_minutes+2*r.turnaround_minutes+ceil(2*r.journey_minutes*r.recovery_percent/100.0))/greatest(5,r.frequency_mins));
IF r.allocated+r.broken>0 AND r.allocated<needed THEN RAISE EXCEPTION 'Route % needs % in-service buses; % allocated',r.number,needed,r.allocated; END IF;
SELECT count(*) INTO crew FROM public.drivers WHERE company_id=NEW.company_id AND route_id=r.id AND role IN ('Driver','Senior Driver');
IF r.allocated>0 AND crew<r.allocated THEN RAISE EXCEPTION 'Route % needs % assigned drivers; % assigned',r.number,r.allocated,crew; END IF;
END LOOP; RETURN NEW; END $function$;